        "complexity": "mid",
        "persona": "guest user",
        "requirement": "As a guest user, I want to browse products in the Women category so that I can see available items",
        "url": SITE_KNOWLEDGE["pages"]["home"]["url"],
        "expected_artifacts": [
            "framework/pages/catalog/category_page.py",
